@using Microsoft.AspNetCore.Components.Forms;

@code {
    private string _id {get;set;}
}

<div>
        <div>
            <InputSelect @bind-Value="_id">
                @if (true)
                {
                    <option>goo</option>
                }
            </InputSelect>
        </div>
</div>
