InitialDocument:
@page "/test"

<div
attr='val'
class=@className>Some Text</div>

@{
@: Hi!
var x = DateTime
    .Now.ToString();
<p>
        @if (true) {
                var t = 1;
        }
        </p>
}

@(DateTime
    .Now
.ToString())

@(
    Foo.Values.Select(f =>
    {
        return f.ToString();
    })
)
