InitialDocument:
@page "/"

@code{
    protected RenderFragment RootFragment() =>
        @<PageTitle>
        @if (true)
        {
            <div class="test"
                accesskey="k">
                Hello
                @if (true)
                {
                    <span>World</span>
                }
                else
                {
                    <span>Not World</span>
                }
            </div>
        }
        </PageTitle>;
}
