@using Microsoft.AspNetCore.Components.Forms;

@code {
    private string _id {get;set;}
}

<div>
    @if (true)
    {
        <div>
            <InputSelect CssClass="goo"
                 @bind-Value="_id"
               @ref="elem"
                CurrentValue="boo">
                    <option>goo</option>
            </InputSelect>
        </div>
    }
</div>
