Welcome.

<div class="goo"
 align="center">
</div>

<PageTitle Title="How is Blazor working for you?"
 Color="Red" />

<PageTitle Title="How is Blazor working for you?"
 Color="Red"></PageTitle>

<PageTitle Title="How is Blazor working for you?"
 Color="Red">
 Hello
 </PageTitle>

@if (true)
{
<div class="goo"
 align="center">
</div>

<PageTitle Title="How is Blazor working for you?"
   Color="Red" />

   <tag attr1="value1"
   attr2="value2"
   attr3="value3"
   />

 <tag attr1="value1"
   attr2="value2"
   attr3="value3"></tag>

 <tag attr1="value1"
   attr2="value2"
   attr3="value3">
Hello
    </tag>

