@page "/"

@code {
    protected RenderFragment RootFragment() => @<text>
        @if (true)
        {
            <div class="test"
                 accesskey="k">
                Hello
                @if (true)
                {
                    <span>World</span>
                }
                else
                {
                    <span>Not World</span>
                }
            </div>
        }
    </text>;
}
