{
<div class="d-flex">
    <div class="d-flex flex-column" style="text-align: end;">
        @if (true)
        {
        <span>
            @((((true) ? 123d : 0d) +
            (true ? 123d : 0d)
            ).ToString("F2", CultureInfo.InvariantCulture)) €
        </span>
        <hr class="my-1" />
        <span>
            @((123d +
            ((true) ? 123d : 0d) +
            (true ? 123d : 0d)
            ).ToString("F2", CultureInfo.InvariantCulture)) €
        </span>
        }
    </div>
</div>
}
