@using System.Text;

<div>
    @(new C()
        .M("Hello")
        .M("World")
        .M(source =>
        {
            if (source.Length > 0)
            {
                source.ToString();
            }
        }))

    @(DateTime.Now)

    @(DateTime
        .Now
        .ToString())
</div>
