InitialDocument:
@using System.Text;

<div>
    @(new C()
            .M("Hello")
        .M("World")
        .M(source =>
        {
        if (source.Length > 0)
        {
        source.ToString();
        }
        }))

    @(DateTime.Now)

    @(DateTime
.Now
.ToString())

                @(   Html.DisplayNameFor (@<text>
        <p >
        <h2 ></h2>
        </p>
        </text>)
        .ToString())

@{
var x = @<p>Hi there!</p>;
}
@x()
@(@x())
</div>

@functions {
    class C
    {
        C M(string a) => this;
        C M(Func<string, C> a) => this;
    }
}
