@page "/"
@code
{
    void T()
    {
        S("first"
            + "second"
            + "third");
    }

string[] S(string s) =>
        s.Split(',')
        . Select(s => s.Trim())
        . ToArray();

RenderFragment R =>
    @<div></div>;
}
