<div class="p-3 pb-0" style="min-height:24rem;">

    @if (productsForExport != null)
    {
        <label class="section-label">
            @(!showResult ? "some label" : "another label")
        </label>

        <div class="row">
            <div class="col">
                @if (!showResult)
                {
                    <label>
                        <input type="checkbox" class="me-2 mt-1" />
                        <span>some label</span>
                    </label>
                }
            </div>

        </div>
    }

</div>

