InitialDocument:
@page "/"
@model IndexModel

<style>
    @@media only screen and (max-width: 600px) {
        body {
            background-color: lightblue;
        }
    }
</style>

<style>
    @@font-face {
        src: url();
    }
</style>

@if (RendererInfo.IsInteractive)
{
<button />
}
