InitialDocument:
@page
@model BlazorApp58.Pages.Index2Model
@{
}

<section class="section">
    <div class="container">
        <h1 class="title">Managed pohotos</h1>
        <p class="subtitle">@Model.ReferenceNumber</p>
    </div>
</section>
<section class="section">
    <div class="container">
        @foreach       (var item in Model.Images)
        {
            <div><div>
        }
    </div>
</section>
