<PageTitle>
    @if (true)
    {
        <p>@DateTime.Now</p>
    }
</PageTitle>

<GridTable>
    @foreach (var row in rows)
    {
        <GridRow @onclick="SelectRow(row)">
            @foreach (var cell in row)
            {
                <GridCell>@cell</GridCell>
            }
        </GridRow>
    }
</GridTable>
